import{_ as l,o,c as i,ah as r}from"./chunks/framework.DjU4PSOm.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":3,"title":"핵심 차별점","slug":"핵심-차별점","link":"#핵심-차별점","children":[]},{"level":3,"title":"기능 기획 브레인스토밍","slug":"기능-기획-브레인스토밍","link":"#기능-기획-브레인스토밍","children":[]},{"level":3,"title":"구현해야 할 내용 (TODO)","slug":"구현해야-할-내용-todo","link":"#구현해야-할-내용-todo","children":[]}],"relativePath":"computer/project/Zing/01. 초기 기획과 기능 브레인스토밍.md","filePath":"computer/project/Zing/01. 초기 기획과 기능 브레인스토밍.md"}'),n={name:"computer/project/Zing/01. 초기 기획과 기능 브레인스토밍.md"};function s(e,t,g,a,_,u){return o(),i("div",null,[...t[0]||(t[0]=[r('<p><em>2026-09-02</em></p><h3 id="핵심-차별점" tabindex="-1">핵심 차별점 <a class="header-anchor" href="#핵심-차별점" aria-label="Permalink to &quot;핵심 차별점&quot;">​</a></h3><ul><li><strong>단계적 소통 해금</strong>: 매칭 직후엔 반응/댓글 등 제한된 방식으로만 소통 가능, 관계(징)가 지속될수록 소통 횟수·방식 제한이 점진적으로 풀림.</li><li><strong>번역</strong>: 해외 교환학생 ↔ 한국 학생 간 언어 장벽을 자동 번역으로 해소.</li></ul><h3 id="기능-기획-브레인스토밍" tabindex="-1">기능 기획 브레인스토밍 <a class="header-anchor" href="#기능-기획-브레인스토밍" aria-label="Permalink to &quot;기능 기획 브레인스토밍&quot;">​</a></h3><ul><li><strong>일기 피드 &amp; 징(Zing)</strong>: 아자르처럼 여러 사람의 일기를 계속 넘겨보다가(랜덤 노출) 마음에 들면 &quot;징&quot;을 보냄. 서로 징을 보내 상호 매칭이 성립하면, 그때부터 랜덤 노출이 아니라 그 상대의 일기를 매일 볼 수 있게 됨. <ul><li>&quot;징&quot;이라는 이름은 영화 &lt;몬스터 호텔&gt;에서 운명의 짝을 만나 첫눈에 강하게 반하는 현상을 뜻하는 용어에서 따옴.</li><li>매칭 후에도 실시간 쌍방향 소통(채팅)은 바로 열리지 않고 제한됨.</li></ul></li><li><strong>단계적 공개</strong>: 처음엔 일기 절반만 공개, 상호 매칭(징) 이후 나머지 절반 공개. (김도균)</li><li><strong>성별</strong>: 비공개. 자율 선택</li><li><strong>동시 매칭 수</strong>: 동시에 몇 명까지 고정 상대로 유지할 수 있는지 — 인원 상한 논의 필요 (미정).</li><li><strong>관계 발전에 따른 제한 완화</strong>: <ul><li>징(매칭) 상태가 오래 지속되면 하루에 소통 가능한 횟수가 늘어남.</li><li>지속되면 소통 방식 제한이 단계적으로 풀림. (김도균)</li></ul></li><li><strong>초기 소통 제한</strong>: 받은 일기에 반응 또는 댓글 달기부터 시작. 관계가 발전하면 댓글 글자 수 등 제한이 확장됨. (김서희)</li><li><strong>일기 글자 수 제한</strong>: 200~600자.</li><li><strong>글감(프롬프트) 기능</strong>: 시쓰는 앱 &quot;씀&quot;처럼 매일 글감을 하나씩 던져주고, 그 글감으로 쓴 다른 사람들의 글을 보여주는 방식 검토. 빈 화면 문제 해결 + 피드 노출 동선으로 활용 가능. (아이디어 단계, 확정 아님)</li></ul><h3 id="구현해야-할-내용-todo" tabindex="-1">구현해야 할 내용 (TODO) <a class="header-anchor" href="#구현해야-할-내용-todo" aria-label="Permalink to &quot;구현해야 할 내용 (TODO)&quot;">​</a></h3><ul><li>[ ] <strong>회원가입/프로필</strong>: 계정 생성, 성별 비공개(자율 선택) 옵션 처리</li><li>[ ] <strong>일기 작성</strong>: 글자 수 200~600자 제한 검증</li><li>[ ] <strong>글감(프롬프트)</strong>: 매일 하나씩 글감 노출, 같은 글감으로 쓴 다른 사람 글 모아보기</li><li>[ ] <strong>일기 피드</strong>: 아자르 스타일 랜덤 넘겨보기 UI</li><li>[ ] <strong>단계적 공개</strong>: 매칭 전 절반만 공개 → 상호 징 이후 전체 공개 로직</li><li>[ ] <strong>징(Zing) 시스템</strong>: 징 보내기, 상호 매칭 감지/저장</li><li>[ ] <strong>매칭 후 노출 전환</strong>: 매칭된 상대는 랜덤 피드 대신 매일 그 사람 일기를 보여주는 로직</li><li>[ ] <strong>동시 매칭 인원 상한</strong>: 정책 수치 결정 필요 (미정) + 상한 도달 시 처리</li><li>[ ] <strong>소통 제한 단계 시스템</strong> (핵심 차별점): 매칭 직후엔 반응/댓글만 가능 → 매칭 지속 기간에 따라 소통 횟수·댓글 글자수 등 제한 완화</li><li>[ ] <strong>채팅 기능</strong>: 실시간 아닌 제한적 방식으로 설계 (제한 해제 조건과 연동)</li><li>[ ] <strong>번역 기능</strong> (핵심 차별점): 일기 작성 언어 ↔ 상대 언어 자동 번역, 글감 다국어 번역 포함</li><li>[ ] <strong>알림</strong>: 매칭 성사, 반응/댓글, 제한 완화 등 이벤트 알림</li></ul>',7)])])}const h=l(n,[["render",s]]);export{d as __pageData,h as default};
